ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    res_code: payload.res_code,
    res_message: payload.res_message,
    result: {
        disputeExDtoList: (payload.result.disputeExDtoList default []) map (dispute) -> {
            amount: dispute.amount,
            createdDate: dispute.createdDate,
            disputeID: dispute.disputeID,
            disputeItemExDtoList: (dispute.disputeItemExDtoList default []) map (item) -> {
                glID: item.glID,
                refInvoiceNumber: item.refInvoiceNumber,
                amount: item.amount,
                glTypeID: item.glTypeID,
                glTypeName: item.glTypeName
            },
            remarks: dispute.remarks,
            status: dispute.status
        },
        resultCode: payload.result.resultCode,
        resultMsg: payload.result.resultMsg
    }
}

%dw 2.0
output application/json
---
{
    "status": "400",
    "code": "BILLING_DISPUTE:INVALID_PARAMS",
    "message": "Customer identification values must be provided.",
    "messageServer": error.description,
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": "Customer identification values must be provided."
        }
    ]
}
